if B.TabById["zbundle_changed"] == nil then B.RegisterTab( {
	id = "zbundle_changed", label = "CHANGED", hint = "Settings changed from their semantic defaults across every registered mod.",
	owner = "zbundle", ownerLabel = "ZBundle", order = 1000000, role = "changed",
	rows = function ( controller )
		local rows = {}
		local function ownerText( english, row, tab )
			local provider = B.Localizers and B.Localizers[tab.owner]
			if type( provider ) == "table" and provider.version == 1 and type( provider.text ) == "function" then
				local ok, result = pcall( provider.text, english, { owner = tab.owner, controller = controller, tab = tab, row = row } )
				if ok and type( result ) == "string" and result ~= "" then return result end
			end
			return english
		end
		for _, tab in ipairs( B.Tabs ) do
			if tab.role ~= "report" and tab.role ~= "changed" and tab.role ~= "mods" then
				for _, row in ipairs( Z.TabRows( tab, controller ) ) do
					if row.kind ~= "button" and not B.RowHostLocked( row, tab, controller or Engine.GetPrimaryController() ) then
					local current = Z.RowGet( row, tab, controller )
					if not Z.IsDefault( current, row ) then
						local copy = {}
						for key, value in pairs( row ) do copy[key] = value end
						local currentLabel = string.upper( tostring( current ) )
						for index, value in ipairs( row.values or {} ) do
							if Z.Same( current, value ) then currentLabel = ownerText( row.labels[index] or currentLabel, row, tab ); break end
						end
						copy.label = string.upper( tostring( tab.ownerLabel or tab.owner or "MOD" ) ) .. " - " .. ownerText( tostring( row.label ), row, tab )
						copy.hint = ownerText( tostring( row.hint or "" ), row, tab )
						copy.sourceOwner = tab.owner
						copy.labelKey, copy.hintKey, copy.choiceKeys = nil, nil, nil
						copy.boundaryKey, copy.scopeKey, copy.titleKey = nil, nil, nil
						copy.boundary = "READ ONLY"
						copy.default = current
						copy.values = { current }
						copy.labels = { currentLabel }
						copy.ztReadOnly = true
						copy.readOnly = true
						copy.writable = false
						copy.editable = false
						table.insert( rows, copy )
					end
					end
				end
			end
		end
		return rows
	end
} ) end

